package main

import (
	"strconv"
	"strings"
)

type RuntimeIssue struct {
	Position Position
	Message  string
}

func runtimeError(position Position, message string) { panic(RuntimeIssue{position, message}) }
func formatOutput(values []Value, position Position) string {
	format := values[0].text()
	argument := 1
	var out strings.Builder
	for i := 0; i < len(format); {
		if format[i] != '%' {
			out.WriteByte(format[i])
			i++
			continue
		}
		i++
		if i < len(format) && format[i] == '%' {
			out.WriteByte('%')
			i++
			continue
		}
		left, zero := false, false
		for i < len(format) && (format[i] == '-' || format[i] == '0') {
			left = left || format[i] == '-'
			zero = zero || format[i] == '0'
			i++
		}
		start := i
		for i < len(format) && digit(format[i]) {
			i++
		}
		width := 0
		if i > start {
			width = int(decimal(format[start:i]))
		}
		precision := -1
		if i < len(format) && format[i] == '.' {
			i++
			start = i
			for i < len(format) && digit(format[i]) {
				i++
			}
			precision = 0
			if i > start {
				precision = int(decimal(format[start:i]))
			}
		}
		if i == len(format) || !strings.ContainsRune("discxo", rune(format[i])) {
			runtimeError(position, "invalid format")
		}
		kind := format[i]
		i++
		if argument == len(values) {
			runtimeError(position, "not enough arguments")
		}
		value := values[argument]
		argument++
		body := ""
		if strings.ContainsRune("dixo", rune(kind)) {
			n := value.number()
			base := 10
			if kind == 'x' {
				base = 16
			} else if kind == 'o' {
				base = 8
			}
			absolute := n
			if n < 0 {
				absolute = -n
			}
			digits := strconv.FormatInt(absolute, base)
			if precision == 0 && n == 0 {
				digits = ""
			}
			if precision > len(digits) {
				digits = strings.Repeat("0", precision-len(digits)) + digits
			}
			body = digits
			if n < 0 {
				body = "-" + body
			}
			if len(body) < width {
				pad := width - len(body)
				if left {
					body += strings.Repeat(" ", pad)
				} else if zero && precision < 0 {
					if n < 0 {
						body = "-" + strings.Repeat("0", pad) + digits
					} else {
						body = strings.Repeat("0", pad) + body
					}
				} else {
					body = strings.Repeat(" ", pad) + body
				}
			}
		} else {
			if kind == 's' {
				body = value.text()
				if precision >= 0 && len(body) > precision {
					body = body[:precision]
				}
			} else if value.Kind == "number" || value.Kind == "strnum" {
				n := value.number()
				if n != 10 && (n < 32 || n > 126) {
					runtimeError(position, "invalid character code")
				}
				body = string(byte(n))
			} else {
				body = value.text()
				if len(body) > 1 {
					body = body[:1]
				}
			}
			if len(body) < width {
				padding := strings.Repeat(" ", width-len(body))
				if left {
					body += padding
				} else {
					body = padding + body
				}
			}
		}
		out.WriteString(body)
	}
	return out.String()
}
func invokeBuiltin(name string, values []Value, position Position) Value {
	switch name {
	case "substr":
		text := values[0].text()
		start := values[1].number()
		end := int64(len(text) + 1)
		if len(values) == 3 {
			end = start + values[2].number()
		}
		start = max(start, 1)
		end = min(end, int64(len(text)+1))
		if end <= start {
			return stringValue("")
		}
		return stringValue(text[int(start-1):int(end-1)])
	case "index":
		text, part := values[0].text(), values[1].text()
		if part == "" {
			return numeric(0)
		}
		return numeric(int64(strings.Index(text, part) + 1))
	case "toupper":
		return stringValue(strings.ToUpper(values[0].text()))
	case "tolower":
		return stringValue(strings.ToLower(values[0].text()))
	case "int":
		return numeric(values[0].number())
	case "sprintf":
		return stringValue(formatOutput(values, position))
	}
	panic("unknown built-in")
}

package main

import (
	"strconv"
	"strings"
)

type Position struct{ Line, Column int }

func (p Position) String() string { return strconv.Itoa(p.Line) + ":" + strconv.Itoa(p.Column) }

type SyntaxIssue struct{ Position Position }
type Token struct {
	Kind, Spelling, Text string
	Number               int64
	Position             Position
}

func letter(c byte) bool { return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' }
func digit(c byte) bool  { return c >= '0' && c <= '9' }
func wordIn(words, value string) bool {
	for _, word := range strings.Fields(words) {
		if word == value {
			return true
		}
	}
	return false
}
func decimal(text string) int64 {
	n, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		panic(err)
	}
	return n
}
func tokenize(source string) []Token {
	tokens := []Token{}
	line, column := 1, 1
	for i := 0; i < len(source); {
		c := source[i]
		position := Position{line, column}
		if c == ' ' {
			i++
			column++
			continue
		}
		if c == '\\' && i+1 < len(source) && source[i+1] == '\n' {
			i += 2
			line++
			column = 1
			continue
		}
		if c == '#' {
			for i < len(source) && source[i] != '\n' {
				i++
				column++
			}
			continue
		}
		if c == '\n' {
			tokens = append(tokens, Token{Kind: "newline", Spelling: "\n", Position: position})
			i++
			line++
			column = 1
			continue
		}
		if digit(c) {
			start := i
			for i < len(source) && digit(source[i]) {
				i++
				column++
			}
			text := source[start:i]
			tokens = append(tokens, Token{Kind: "number", Spelling: text, Number: decimal(text), Position: position})
			continue
		}
		if letter(c) || c == '_' {
			start := i
			for i < len(source) && (letter(source[i]) || digit(source[i]) || source[i] == '_') {
				i++
				column++
			}
			text := source[start:i]
			kind := "name"
			if wordIn("BEGIN END function if else while for do break continue next exit return delete in getline print printf", text) {
				kind = "keyword"
			} else if wordIn("length substr index split sprintf toupper tolower close int", text) {
				kind = "builtin"
			} else if i < len(source) && source[i] == '(' {
				kind = "function_name"
			}
			tokens = append(tokens, Token{Kind: kind, Spelling: text, Position: position})
			continue
		}
		if c == '"' {
			start := i
			i++
			column++
			var value strings.Builder
			for {
				if i == len(source) || source[i] == '\n' {
					panic(SyntaxIssue{position})
				}
				c = source[i]
				i++
				column++
				if c == '"' {
					break
				}
				if c == '\\' {
					slash := Position{line, column - 1}
					if i == len(source) {
						panic(SyntaxIssue{position})
					}
					c = source[i]
					i++
					column++
					switch c {
					case 'n':
						c = '\n'
					case 't':
						c = '\t'
					case '\\', '"', '/':
					default:
						panic(SyntaxIssue{slash})
					}
				}
				value.WriteByte(c)
			}
			tokens = append(tokens, Token{Kind: "string", Spelling: source[start:i], Text: value.String(), Position: position})
			continue
		}
		symbol := ""
		if i+1 < len(source) && wordIn("+= -= *= /= %= ^= == <= >= != ++ -- && || >>", source[i:i+2]) {
			symbol = source[i : i+2]
		} else if strings.ContainsRune("+-*/%^!><?:=()[]{},;$", rune(c)) {
			symbol = source[i : i+1]
		}
		if symbol == "" {
			panic(SyntaxIssue{position})
		}
		tokens = append(tokens, Token{Kind: "symbol", Spelling: symbol, Position: position})
		i += len(symbol)
		column += len(symbol)
	}
	return append(tokens, Token{Kind: "end", Position: Position{strings.Count(source, "\n") + 1, 1}})
}

package main

import (
	"fmt"
	"sort"
	"strings"
)

var specialNames = []string{"FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP"}

type StaticIssue struct {
	Position Position
	Priority int
	Message  string
}
type Analysis struct {
	Items, Functions, Rules []*Item
	FunctionTable           map[string]*Item
	Globals                 map[string]bool
	Arrays                  map[Binding]bool
	Expressions             []*Expr
	Statements              []*Statement
	Lines                   map[int]bool
	Errors                  []StaticIssue
}

func newAnalysis(items []*Item) *Analysis {
	a := &Analysis{Items: items, FunctionTable: map[string]*Item{}, Globals: map[string]bool{}, Arrays: map[Binding]bool{}, Lines: map[int]bool{}}
	for _, name := range specialNames {
		a.Globals[name] = true
	}
	for _, item := range items {
		if item.Kind == "function" {
			a.Functions = append(a.Functions, item)
		} else {
			a.Rules = append(a.Rules, item)
		}
	}
	return a
}
func (a *Analysis) issue(position Position, priority int, message string) {
	a.Errors = append(a.Errors, StaticIssue{position, priority, message})
}
func (a *Analysis) expression(e *Expr, function *Item) {
	if e == nil {
		return
	}
	a.Expressions = append(a.Expressions, e)
	if e.Kind == "name" || e.Kind == "array" || e.Kind == "parameter" {
		e.Binding = Binding{Name: e.Name}
		if function != nil && function.ParameterNames[e.Name] {
			e.Binding.Function = function
		} else {
			a.Globals[e.Name] = true
		}
		if a.FunctionTable[e.Name] != nil {
			a.issue(e.Position, 2, "function "+e.Name+" used as variable")
		}
	} else if e.Kind == "call" {
		e.Function = a.FunctionTable[e.Name]
		if e.Function == nil {
			a.issue(e.Position, 3, "undefined function "+e.Name)
		} else if len(e.Args) > len(e.Function.Parameters) {
			a.issue(e.Position, 4, "too many arguments to "+e.Name)
		}
	}
	a.expression(e.Left, function)
	a.expression(e.Right, function)
	a.expression(e.Third, function)
	for _, argument := range e.Args {
		a.expression(argument, function)
	}
}
func (a *Analysis) statement(s *Statement, function *Item) {
	if s == nil {
		return
	}
	a.Statements = append(a.Statements, s)
	if s.Kind != "block" && s.Kind != "empty" {
		a.Lines[s.Position.Line] = true
	}
	for _, e := range s.Exprs {
		a.expression(e, function)
	}
	a.expression(s.Variable, function)
	a.expression(s.Array, function)
	a.expression(s.Redirect, function)
	for _, child := range s.Statements {
		a.statement(child, function)
	}
	a.statement(s.Body, function)
	a.statement(s.Else, function)
}
func (a *Analysis) prepare() {
	for _, function := range a.Functions {
		if a.FunctionTable[function.Name] != nil {
			a.issue(function.NamePosition, 0, "function "+function.Name+" redefined")
		} else {
			a.FunctionTable[function.Name] = function
		}
		function.ParameterNames = map[string]bool{}
		for _, parameter := range function.Parameters {
			if function.ParameterNames[parameter.Name] {
				a.issue(parameter.Position, 1, "duplicate parameter "+parameter.Name)
			}
			function.ParameterNames[parameter.Name] = true
		}
	}
	for _, item := range a.Items {
		var function *Item
		if item.Kind == "function" {
			function = item
		}
		for _, parameter := range item.Parameters {
			a.expression(parameter, function)
		}
		for _, pattern := range item.Patterns {
			a.expression(pattern, function)
		}
		a.statement(item.Body, function)
	}
	if len(a.Errors) > 0 {
		sort.SliceStable(a.Errors, func(i, j int) bool {
			x, y := a.Errors[i], a.Errors[j]
			if x.Position.Line != y.Position.Line {
				return x.Position.Line < y.Position.Line
			}
			if x.Position.Column != y.Position.Column {
				return x.Position.Column < y.Position.Column
			}
			return x.Priority < y.Priority
		})
		panic(a.Errors[0])
	}
	links := [][2]Binding{}
	for _, e := range a.Expressions {
		switch e.Kind {
		case "array":
			a.Arrays[e.Binding] = true
		case "membership":
			a.Arrays[e.Right.Binding] = true
		case "builtin":
			if e.Name == "split" {
				a.Arrays[e.Args[1].Binding] = true
			}
		case "call":
			for i, argument := range e.Args {
				if argument.Kind == "name" {
					links = append(links, [2]Binding{argument.Binding, e.Function.Parameters[i].Binding})
				}
			}
		}
	}
	for _, s := range a.Statements {
		if s.Kind == "delete" || s.Kind == "for_in" {
			a.Arrays[s.Array.Binding] = true
		}
	}
	for {
		changed := false
		for _, link := range links {
			if a.Arrays[link[0]] && !a.Arrays[link[1]] {
				a.Arrays[link[1]] = true
				changed = true
			}
			if a.Arrays[link[1]] && !a.Arrays[link[0]] {
				a.Arrays[link[0]] = true
				changed = true
			}
		}
		if !changed {
			break
		}
	}
}

type Cell struct {
	Value Value
	Array map[string]Value
}
type Location struct {
	Kind  string
	Cell  *Cell
	Key   string
	Index int
	NF    bool
}
type Transfer struct {
	Kind  string
	Value Value
}

func trap(action func()) (transfer *Transfer) {
	defer func() {
		if failure := recover(); failure != nil {
			if t, ok := failure.(Transfer); ok {
				transfer = &t
			} else {
				panic(failure)
			}
		}
	}()
	action()
	return nil
}
func arithmetic(op string, a, b Value, position Position) Value {
	x, y := a.number(), b.number()
	var result int64
	switch op {
	case "+":
		result = x + y
	case "-":
		result = x - y
	case "*":
		result = x * y
	case "/", "%":
		if y == 0 {
			runtimeError(position, "division by zero")
		}
		result = x / y
		if op == "%" {
			result = x - result*y
		}
	case "^":
		if y < 0 {
			runtimeError(position, "negative exponent")
		}
		result = 1
		for y > 0 {
			if y&1 != 0 {
				result *= x
			}
			y >>= 1
			if y > 0 {
				x *= x
			}
		}
	}
	return numeric(result)
}

type Engine struct {
	Analysis                 *Analysis
	Options                  []Option
	Operands                 []*Operand
	Globals                  map[string]*Cell
	Locals                   []map[string]*Cell
	Record                   *Record
	Streams                  *Streams
	Lines                    map[int]int
	Phase                    string
	ExitStatus               int64
	Error                    *RuntimeIssue
	OperandIndex, InputIndex int
	Current                  *Operand
	InputLines               []string
}

func newEngine(a *Analysis, options []Option, operands []*Operand) *Engine {
	e := &Engine{Analysis: a, Options: options, Operands: operands, Globals: map[string]*Cell{}, Streams: newStreams(), Lines: map[int]int{}, Phase: "BEGIN"}
	for name := range a.Globals {
		cell := &Cell{}
		if a.Arrays[Binding{Name: name}] {
			cell.Array = map[string]Value{}
		}
		e.Globals[name] = cell
	}
	for _, name := range specialNames {
		e.Globals[name].Value = numeric(0)
	}
	e.Globals["FILENAME"].Value = stringValue("")
	e.Globals["FS"].Value = stringValue(" ")
	e.Globals["OFS"].Value = stringValue(" ")
	e.Globals["ORS"].Value = stringValue("\n")
	e.Globals["SUBSEP"].Value = stringValue(string(byte(28)))
	for line := range a.Lines {
		e.Lines[line] = 0
	}
	e.Record = &Record{Zero: stringValue(""), Global: e.global}
	return e
}
func (e *Engine) cell(binding Binding) *Cell {
	if binding.Function != nil {
		return e.Locals[len(e.Locals)-1][binding.Name]
	}
	return e.Globals[binding.Name]
}
func (e *Engine) global(name string) Value {
	if name == "NF" {
		return numeric(int64(len(e.Record.Fields)))
	}
	return e.Globals[name].Value
}
func (e *Engine) assignInput(name, text string) {
	cell := e.Globals[name]
	if cell == nil {
		cell = &Cell{}
		e.Globals[name] = cell
	}
	cell.Value = inputValue(text)
}
func (e *Engine) subscript(args []*Expr) string {
	values := []string{}
	for _, arg := range args {
		values = append(values, e.evaluate(arg).text())
	}
	return strings.Join(values, e.global("SUBSEP").text())
}
func (e *Engine) location(node *Expr) Location {
	switch node.Kind {
	case "name":
		return Location{Kind: "variable", Cell: e.cell(node.Binding), NF: node.Binding.Function == nil && node.Name == "NF"}
	case "array":
		key := e.subscript(node.Args)
		return Location{Kind: "array", Cell: e.cell(node.Binding), Key: key}
	}
	index := e.evaluate(node.Left).number()
	if index < 0 {
		runtimeError(node.Position, "negative field index")
	}
	return Location{Kind: "field", Index: int(index)}
}
func (e *Engine) read(location Location) Value {
	switch location.Kind {
	case "field":
		return e.Record.read(location.Index)
	case "array":
		value, exists := location.Cell.Array[location.Key]
		if !exists {
			location.Cell.Array[location.Key] = Value{}
		}
		return value
	}
	if location.NF {
		return numeric(int64(len(e.Record.Fields)))
	}
	return location.Cell.Value
}
func (e *Engine) store(location Location, value Value, position Position) {
	switch location.Kind {
	case "field":
		e.Record.write(location.Index, value)
	case "array":
		location.Cell.Array[location.Key] = value
	default:
		if location.NF {
			n := value.number()
			if n < 0 {
				runtimeError(position, "negative NF")
			}
			e.Record.resize(int(n))
		} else {
			location.Cell.Value = value
		}
	}
}
func (e *Engine) evaluate(node *Expr) Value {
	switch node.Kind {
	case "number", "string":
		return node.Value
	case "name", "array", "field":
		return e.read(e.location(node))
	case "paren":
		return e.evaluate(node.Left)
	case "assignment":
		location := e.location(node.Left)
		value := e.evaluate(node.Right)
		if node.Op != "=" {
			value = arithmetic(node.Op[:1], e.read(location), value, node.Position)
		}
		e.store(location, value, node.Position)
		return e.read(location)
	case "increment":
		location := e.location(node.Left)
		old := e.read(location).number()
		value := old + 1
		if node.Op == "--" {
			value = old - 1
		}
		e.store(location, numeric(value), node.Position)
		if node.Prefix {
			return numeric(value)
		}
		return numeric(old)
	case "conditional":
		if e.evaluate(node.Left).truth() {
			return e.evaluate(node.Right)
		}
		return e.evaluate(node.Third)
	case "unary":
		value := e.evaluate(node.Left)
		if node.Op == "!" {
			return boolean(!value.truth())
		}
		n := value.number()
		if node.Op == "-" {
			n = -n
		}
		return numeric(n)
	case "membership":
		key := e.subscript(node.Args)
		_, exists := e.cell(node.Right.Binding).Array[key]
		return boolean(exists)
	case "binary":
		first := e.evaluate(node.Left)
		if node.Op == "||" && first.truth() {
			return numeric(1)
		}
		if node.Op == "&&" && !first.truth() {
			return numeric(0)
		}
		second := e.evaluate(node.Right)
		if node.Op == "&&" || node.Op == "||" {
			return boolean(second.truth())
		}
		if node.Op == "concat" {
			return stringValue(first.text() + second.text())
		}
		if wordIn("< <= == != >= >", node.Op) {
			order := compare(first, second)
			result := false
			switch node.Op {
			case "<":
				result = order < 0
			case "<=":
				result = order <= 0
			case "==":
				result = order == 0
			case "!=":
				result = order != 0
			case ">=":
				result = order >= 0
			case ">":
				result = order > 0
			}
			return boolean(result)
		}
		return arithmetic(node.Op, first, second, node.Position)
	case "call":
		return e.call(node)
	case "builtin":
		return e.builtin(node)
	case "getline":
		return e.getline(node)
	}
	panic("unknown expression")
}
func boolean(value bool) Value {
	if value {
		return numeric(1)
	}
	return numeric(0)
}
func (e *Engine) call(node *Expr) Value {
	function := node.Function
	locals := map[string]*Cell{}
	for i, parameter := range function.Parameters {
		if e.Analysis.Arrays[parameter.Binding] {
			if i < len(node.Args) {
				locals[parameter.Name] = e.cell(node.Args[i].Binding)
			} else {
				locals[parameter.Name] = &Cell{Array: map[string]Value{}}
			}
		} else {
			value := Value{}
			if i < len(node.Args) {
				value = e.evaluate(node.Args[i])
			}
			locals[parameter.Name] = &Cell{Value: value}
		}
	}
	function.Calls++
	function.Active++
	function.Depth = max(function.Depth, function.Active)
	e.Locals = append(e.Locals, locals)
	defer func() {
		e.Locals = e.Locals[:len(e.Locals)-1]
		function.Active--
	}()
	transfer := trap(func() { e.statement(function.Body) })
	if transfer != nil {
		if transfer.Kind == "return" {
			return transfer.Value
		}
		panic(*transfer)
	}
	return Value{}
}
func (e *Engine) builtin(node *Expr) Value {
	switch node.Name {
	case "length":
		if len(node.Args) == 0 {
			return numeric(int64(len(e.Record.Zero.text())))
		}
		arg := node.Args[0]
		if arg.Kind == "name" && e.Analysis.Arrays[arg.Binding] {
			return numeric(int64(len(e.cell(arg.Binding).Array)))
		}
		return numeric(int64(len(e.evaluate(arg).text())))
	case "split":
		text := e.evaluate(node.Args[0]).text()
		separator := ""
		if len(node.Args) == 3 {
			separator = e.evaluate(node.Args[2]).text()
		} else {
			separator = e.global("FS").text()
		}
		array := e.cell(node.Args[1].Binding).Array
		clear(array)
		pieces := splitPieces(text, separator)
		for i, piece := range pieces {
			array[fmt.Sprint(i+1)] = inputValue(piece)
		}
		return numeric(int64(len(pieces)))
	case "close":
		return numeric(e.Streams.close(e.evaluate(node.Args[0]).text()))
	}
	values := []Value{}
	for _, arg := range node.Args {
		values = append(values, e.evaluate(arg))
	}
	return invokeBuiltin(node.Name, values, node.Position)
}
func (e *Engine) getline(node *Expr) Value {
	status, line := 0, ""
	if node.Right != nil {
		name := e.evaluate(node.Right).text()
		status, line = e.Streams.getline(name)
	} else if e.Phase != "END" {
		var found bool
		line, found = e.nextRecord()
		if found {
			status = 1
		}
	}
	if status == 1 {
		if node.Left == nil {
			e.Record.set(line)
		} else {
			location := e.location(node.Left)
			e.store(location, inputValue(line), node.Position)
		}
	}
	return numeric(int64(status))
}
func (e *Engine) output(node *Statement) {
	values := []Value{}
	for _, arg := range node.Exprs {
		values = append(values, e.evaluate(arg))
	}
	text := ""
	if node.Kind == "print" {
		if len(values) == 0 {
			values = append(values, e.Record.Zero)
		}
		parts := []string{}
		for _, value := range values {
			parts = append(parts, value.text())
		}
		text = strings.Join(parts, e.global("OFS").text()) + e.global("ORS").text()
	} else {
		text = formatOutput(values, node.Position)
	}
	name := ""
	if node.Redirect != nil {
		name = e.evaluate(node.Redirect).text()
	}
	e.Streams.write(text, name, node.RedirectMode, node.RedirectPosition)
}
func (e *Engine) loopBody(body *Statement) bool {
	transfer := trap(func() { e.statement(body) })
	if transfer == nil {
		return true
	}
	if transfer.Kind == "break" {
		return false
	}
	if transfer.Kind == "continue" {
		return true
	}
	panic(*transfer)
}
func (e *Engine) statement(node *Statement) {
	if node.Kind == "block" {
		for _, child := range node.Statements {
			e.statement(child)
		}
		return
	}
	if node.Kind == "empty" {
		return
	}
	e.Lines[node.Position.Line]++
	switch node.Kind {
	case "expression":
		e.evaluate(node.Exprs[0])
	case "print", "printf":
		e.output(node)
	case "if":
		if e.evaluate(node.Exprs[0]).truth() {
			e.statement(node.Body)
		} else if node.Else != nil {
			e.statement(node.Else)
		}
	case "while":
		for e.evaluate(node.Exprs[0]).truth() {
			if !e.loopBody(node.Body) {
				break
			}
		}
	case "do":
		for {
			if !e.loopBody(node.Body) || !e.evaluate(node.Exprs[0]).truth() {
				break
			}
		}
	case "for":
		if node.Exprs[0] != nil {
			e.evaluate(node.Exprs[0])
		}
		for node.Exprs[1] == nil || e.evaluate(node.Exprs[1]).truth() {
			if !e.loopBody(node.Body) {
				break
			}
			if node.Exprs[2] != nil {
				e.evaluate(node.Exprs[2])
			}
		}
	case "for_in":
		keys := orderedSubscripts(e.cell(node.Array.Binding).Array)
		for _, key := range keys {
			location := e.location(node.Variable)
			e.store(location, inputValue(key), node.Variable.Position)
			if !e.loopBody(node.Body) {
				break
			}
		}
	case "delete":
		array := e.cell(node.Array.Binding).Array
		if node.WholeDelete {
			clear(array)
		} else {
			key := e.subscript(node.Exprs)
			delete(array, key)
		}
	case "next":
		if e.Phase == "BEGIN" || e.Phase == "END" {
			runtimeError(node.Position, "next used in BEGIN or END")
		}
		panic(Transfer{Kind: "next"})
	case "exit":
		if len(node.Exprs) > 0 {
			e.ExitStatus = e.evaluate(node.Exprs[0]).number()
		}
		panic(Transfer{Kind: "exit"})
	case "return":
		value := Value{}
		if len(node.Exprs) > 0 {
			value = e.evaluate(node.Exprs[0])
		}
		panic(Transfer{Kind: "return", Value: value})
	case "break", "continue":
		panic(Transfer{Kind: node.Kind})
	}
}
func (e *Engine) nextRecord() (string, bool) {
	for {
		if e.InputIndex < len(e.InputLines) {
			line := e.InputLines[e.InputIndex]
			e.InputIndex++
			e.Current.Records++
			e.Globals["NR"].Value = numeric(e.global("NR").number() + 1)
			e.Globals["FNR"].Value = numeric(e.global("FNR").number() + 1)
			return line, true
		}
		if e.OperandIndex == len(e.Operands) {
			return "", false
		}
		operand := e.Operands[e.OperandIndex]
		e.OperandIndex++
		if operand.Kind == "assignment" {
			e.assignInput(operand.Name, operand.Value)
		} else {
			e.Current = operand
			e.InputLines = readRecords(operand.Name)
			e.InputIndex = 0
			e.Globals["FILENAME"].Value = stringValue(operand.Name)
			e.Globals["FNR"].Value = numeric(0)
		}
	}
}
func (e *Engine) actions(phase string) {
	e.Phase = phase
	for _, rule := range e.Analysis.Rules {
		if rule.Flavor == phase {
			rule.Count++
			e.statement(rule.Body)
		}
	}
}
func (e *Engine) matches(rule *Item) bool {
	if rule.Flavor == "all" {
		return true
	}
	if rule.Flavor == "pattern" {
		return e.evaluate(rule.Patterns[0]).truth()
	}
	if !rule.Inside && e.evaluate(rule.Patterns[0]).truth() {
		rule.Inside = true
	}
	if !rule.Inside {
		return false
	}
	if e.evaluate(rule.Patterns[1]).truth() {
		rule.Inside = false
	}
	return true
}
func (e *Engine) records() {
	any := false
	for _, rule := range e.Analysis.Rules {
		any = any || rule.Flavor != "BEGIN"
	}
	if !any {
		return
	}
	e.Phase = "records"
	for {
		line, found := e.nextRecord()
		if !found {
			return
		}
		e.Record.set(line)
		transfer := trap(func() {
			for _, rule := range e.Analysis.Rules {
				if rule.Flavor == "BEGIN" || rule.Flavor == "END" {
					continue
				}
				if e.matches(rule) {
					rule.Count++
					if rule.Body == nil {
						e.Streams.write(e.Record.Zero.text()+e.global("ORS").text(), "", "", Position{})
					} else {
						e.statement(rule.Body)
					}
				}
			}
		})
		if transfer != nil && transfer.Kind != "next" {
			panic(*transfer)
		}
	}
}
func (e *Engine) execute() {
	defer func() {
		if failure := recover(); failure != nil {
			if issue, ok := failure.(RuntimeIssue); ok {
				e.Error = &issue
			} else {
				panic(failure)
			}
		}
	}()
	for _, option := range e.Options {
		e.assignInput(option.Name, option.Value)
	}
	transfer := trap(func() {
		e.actions("BEGIN")
		e.records()
	})
	if transfer != nil && transfer.Kind != "exit" {
		panic(*transfer)
	}
	transfer = trap(func() { e.actions("END") })
	if transfer != nil && transfer.Kind != "exit" {
		panic(*transfer)
	}
}
func (e *Engine) statistics() []string {
	status := fmt.Sprintf("status: exit %d", e.ExitStatus)
	if e.Error != nil {
		status = "status: runtime error at " + e.Error.Position.String() + ": " + e.Error.Message
	}
	out := []string{status, "[inputs]"}
	for _, operand := range e.Operands {
		if operand.Kind == "file" {
			out = append(out, fmt.Sprintf("%s records=%d", operand.Name, operand.Records))
		}
	}
	out = append(out, "[getline]")
	for _, name := range e.Streams.InputOrder {
		source := e.Streams.Inputs[name]
		suffix := "missing"
		if source.EverOpened {
			suffix = fmt.Sprintf("reads=%d", source.Reads)
		}
		out = append(out, name+" "+suffix)
	}
	out = append(out, "[rules]")
	for _, rule := range e.Analysis.Rules {
		out = append(out, fmt.Sprintf("%s %s count=%d", rule.Position.String(), rule.Flavor, rule.Count))
	}
	out = append(out, "[functions]")
	for _, function := range e.Analysis.Functions {
		out = append(out, fmt.Sprintf("%s calls=%d depth=%d", function.Name, function.Calls, function.Depth))
	}
	out = append(out, "[outputs]", fmt.Sprintf("stdout.txt writes=%d bytes=%d", e.Streams.Stdout.Writes, len(e.Streams.Stdout.content())))
	for _, name := range e.Streams.OutputOrder {
		stream := e.Streams.Outputs[name]
		out = append(out, fmt.Sprintf("%s writes=%d bytes=%d", name, stream.Writes, len(stream.content())))
	}
	lineNumbers := []int{}
	for line := range e.Lines {
		lineNumbers = append(lineNumbers, line)
	}
	sort.Ints(lineNumbers)
	out = append(out, "[lines]")
	for _, line := range lineNumbers {
		out = append(out, fmt.Sprintf("%d count=%d", line, e.Lines[line]))
	}
	globalNames := []string{}
	for name := range e.Globals {
		globalNames = append(globalNames, name)
	}
	sort.Strings(globalNames)
	out = append(out, "[globals]")
	for _, name := range globalNames {
		text := describe(e.global(name))
		if e.Analysis.Arrays[Binding{Name: name}] {
			text = fmt.Sprintf("array (%d)", len(e.Globals[name].Array))
		}
		out = append(out, name+" = "+text)
	}
	return out
}
func process(options []Option, operands []*Operand, source string) (streams *Streams, statistics []string) {
	streams = newStreams()
	defer func() {
		if failure := recover(); failure != nil {
			switch issue := failure.(type) {
			case SyntaxIssue:
				statistics = []string{"status: syntax error at " + issue.Position.String()}
			case StaticIssue:
				statistics = []string{"status: error at " + issue.Position.String() + ": " + issue.Message}
			default:
				panic(failure)
			}
		}
	}()
	parser := Parser{Tokens: tokenize(source)}
	analysis := newAnalysis(parser.parse())
	analysis.prepare()
	engine := newEngine(analysis, options, operands)
	engine.execute()
	return engine.Streams, engine.statistics()
}
func main() {
	options, operands := parseArguments(textLines(readText("input/args.txt")))
	streams, statistics := process(options, operands, readText("input/program.awk"))
	streams.save()
	writeFile("output/stats.txt", strings.Join(statistics, "\n")+"\n")
}

package main

type Binding struct {
	Function *Item
	Name     string
}
type Expr struct {
	Kind, Name, Op     string
	Position           Position
	Value              Value
	Left, Right, Third *Expr
	Args               []*Expr
	Binding            Binding
	Function           *Item
	Prefix             bool
}
type Statement struct {
	Kind             string
	Position         Position
	Exprs            []*Expr
	Body, Else       *Statement
	Statements       []*Statement
	Variable, Array  *Expr
	Redirect         *Expr
	RedirectMode     string
	RedirectPosition Position
	WholeDelete      bool
}
type Item struct {
	Kind, Name, Flavor          string
	Position, NamePosition      Position
	Parameters                  []*Expr
	ParameterNames              map[string]bool
	Body                        *Statement
	Patterns                    []*Expr
	Count, Calls, Active, Depth int
	Inside                      bool
}
type Parser struct {
	Tokens       []Token
	Index, Loops int
	Function     bool
	Phase        string
}

func (p *Parser) peek() Token { return p.Tokens[p.Index] }
func (p *Parser) take() Token {
	token := p.peek()
	p.Index++
	return token
}
func (p *Parser) fail() { panic(SyntaxIssue{p.peek().Position}) }
func (p *Parser) accept(spelling string) bool {
	if p.peek().Spelling != spelling {
		return false
	}
	p.Index++
	return true
}
func (p *Parser) expect(spelling string) Token {
	if p.peek().Spelling != spelling {
		p.fail()
	}
	return p.take()
}
func (p *Parser) newlines() {
	for p.accept("\n") {
	}
}
func (p *Parser) name() *Expr {
	if p.peek().Kind != "name" {
		p.fail()
	}
	token := p.take()
	return &Expr{Kind: "name", Name: token.Spelling, Position: token.Position}
}
func lvalue(e *Expr) bool { return e.Kind == "name" || e.Kind == "array" || e.Kind == "field" }
func (p *Parser) parse() []*Item {
	items := []*Item{}
	for p.peek().Kind != "end" {
		if p.accept("\n") || p.accept(";") {
			continue
		}
		start := p.peek()
		if p.accept("function") {
			if p.peek().Kind != "name" && p.peek().Kind != "function_name" {
				p.fail()
			}
			name := p.take()
			p.expect("(")
			parameters := []*Expr{}
			if p.peek().Spelling != ")" {
				for {
					parameter := p.name()
					parameter.Kind = "parameter"
					parameters = append(parameters, parameter)
					if !p.accept(",") {
						break
					}
					p.newlines()
				}
			}
			p.expect(")")
			p.newlines()
			p.Function = true
			body := p.block()
			p.Function = false
			items = append(items, &Item{Kind: "function", Name: name.Spelling, NamePosition: name.Position, Position: start.Position, Parameters: parameters, Body: body})
			continue
		}
		flavor := ""
		patterns := []*Expr{}
		if start.Spelling == "BEGIN" || start.Spelling == "END" {
			flavor = p.take().Spelling
		} else if start.Spelling == "{" {
			flavor = "all"
		} else {
			patterns = append(patterns, p.expression(true))
			if p.accept(",") {
				p.newlines()
				patterns = append(patterns, p.expression(true))
			}
			flavor = "pattern"
			if len(patterns) == 2 {
				flavor = "range"
			}
		}
		p.Phase = flavor
		var body *Statement
		if flavor == "BEGIN" || flavor == "END" || flavor == "all" || p.peek().Spelling == "{" {
			body = p.block()
		} else if p.peek().Spelling != "\n" && p.peek().Spelling != ";" && p.peek().Kind != "end" {
			p.fail()
		}
		p.Phase = ""
		items = append(items, &Item{Kind: "rule", Flavor: flavor, Position: start.Position, Patterns: patterns, Body: body})
	}
	return items
}
func (p *Parser) block() *Statement {
	opening := p.expect("{")
	out := &Statement{Kind: "block", Position: opening.Position}
	for p.peek().Spelling != "}" {
		if p.accept("\n") || p.accept(";") {
			continue
		}
		out.Statements = append(out.Statements, p.statement())
	}
	p.expect("}")
	return out
}
func (p *Parser) condition() *Expr {
	p.expect("(")
	value := p.expression(true)
	p.expect(")")
	return value
}
func (p *Parser) loopBody() *Statement {
	p.newlines()
	p.Loops++
	body := p.statement()
	p.Loops--
	return body
}
func (p *Parser) terminator() {
	if p.accept(";") || p.accept("\n") {
		return
	}
	if p.peek().Spelling != "}" {
		p.fail()
	}
}
func (p *Parser) statement() *Statement {
	token := p.peek()
	kind := token.Spelling
	if kind == "{" {
		return p.block()
	}
	if p.accept(";") {
		return &Statement{Kind: "empty", Position: token.Position}
	}
	out := &Statement{Kind: kind, Position: token.Position}
	switch kind {
	case "if":
		p.take()
		out.Exprs = []*Expr{p.condition()}
		p.newlines()
		out.Body = p.statement()
		p.newlines()
		if p.accept("else") {
			p.newlines()
			out.Else = p.statement()
		}
		return out
	case "while":
		p.take()
		out.Exprs = []*Expr{p.condition()}
		out.Body = p.loopBody()
		return out
	case "do":
		p.take()
		out.Body = p.loopBody()
		p.newlines()
		p.expect("while")
		out.Exprs = []*Expr{p.condition()}
		p.terminator()
		return out
	case "for":
		p.take()
		p.expect("(")
		if p.Index+3 < len(p.Tokens) && p.Tokens[p.Index].Kind == "name" && p.Tokens[p.Index+1].Spelling == "in" && p.Tokens[p.Index+2].Kind == "name" && p.Tokens[p.Index+3].Spelling == ")" {
			out.Kind = "for_in"
			out.Variable = p.name()
			p.expect("in")
			out.Array = p.name()
			p.expect(")")
			out.Body = p.loopBody()
			return out
		}
		out.Exprs = make([]*Expr, 3)
		if p.peek().Spelling != ";" {
			out.Exprs[0] = p.expression(true)
		}
		p.expect(";")
		p.newlines()
		if p.peek().Spelling != ";" {
			out.Exprs[1] = p.expression(true)
		}
		p.expect(";")
		p.newlines()
		if p.peek().Spelling != ")" {
			out.Exprs[2] = p.expression(true)
		}
		p.expect(")")
		out.Body = p.loopBody()
		return out
	case "print", "printf":
		p.take()
		p.output(out)
	case "delete":
		p.take()
		out.Array = p.name()
		out.WholeDelete = true
		if p.accept("[") {
			out.WholeDelete = false
			out.Exprs = p.expressionList(true)
			p.expect("]")
		}
	case "next", "break", "continue", "exit", "return":
		p.take()
		if kind == "next" && !p.Function && (p.Phase == "BEGIN" || p.Phase == "END") || kind == "return" && !p.Function || (kind == "break" || kind == "continue") && p.Loops == 0 {
			panic(SyntaxIssue{token.Position})
		}
		if (kind == "exit" || kind == "return") && !wordIn("; }", p.peek().Spelling) && p.peek().Spelling != "\n" {
			out.Exprs = []*Expr{p.expression(true)}
		}
	default:
		out.Kind = "expression"
		out.Exprs = []*Expr{p.expression(true)}
	}
	p.terminator()
	return out
}
func (p *Parser) parenthesizedOutput() bool {
	if p.peek().Spelling != "(" {
		return false
	}
	depth := 0
	for i := p.Index; i < len(p.Tokens); i++ {
		switch p.Tokens[i].Spelling {
		case "(":
			depth++
		case ")":
			depth--
			if depth == 0 {
				if i+1 == len(p.Tokens) {
					return false
				}
				next := p.Tokens[i+1]
				return next.Kind == "end" || next.Spelling == "\n" || wordIn("; } > >>", next.Spelling)
			}
		}
	}
	return false
}
func (p *Parser) output(out *Statement) {
	if p.parenthesizedOutput() {
		p.expect("(")
		out.Exprs = p.expressionList(true)
		p.expect(")")
	} else if p.peek().Spelling != "\n" && !wordIn("; } > >>", p.peek().Spelling) {
		out.Exprs = p.expressionList(false)
	}
	if out.Kind == "printf" && len(out.Exprs) == 0 {
		p.fail()
	}
	if p.peek().Spelling == ">" || p.peek().Spelling == ">>" {
		redirect := p.take()
		out.RedirectMode = redirect.Spelling
		out.RedirectPosition = redirect.Position
		out.Redirect = p.concatenation()
	}
}
func (p *Parser) expressionList(greater bool) []*Expr {
	out := []*Expr{p.expression(greater)}
	for p.accept(",") {
		p.newlines()
		out = append(out, p.expression(greater))
	}
	return out
}
func (p *Parser) expression(greater bool) *Expr {
	left := p.conditional(greater)
	if lvalue(left) && wordIn("= += -= *= /= %= ^=", p.peek().Spelling) {
		op := p.take()
		return &Expr{Kind: "assignment", Op: op.Spelling, Position: op.Position, Left: left, Right: p.expression(greater)}
	}
	return left
}
func (p *Parser) conditional(greater bool) *Expr {
	condition := p.logical(0, greater)
	if !p.accept("?") {
		return condition
	}
	position := p.Tokens[p.Index-1].Position
	first := p.conditional(greater)
	p.expect(":")
	second := p.conditional(greater)
	return &Expr{Kind: "conditional", Position: position, Left: condition, Right: first, Third: second}
}
func binary(op Token, left, right *Expr) *Expr {
	return &Expr{Kind: "binary", Op: op.Spelling, Position: op.Position, Left: left, Right: right}
}
func (p *Parser) logical(level int, greater bool) *Expr {
	if level == 2 {
		return p.membership(greater)
	}
	op := "||"
	if level == 1 {
		op = "&&"
	}
	left := p.logical(level+1, greater)
	for p.peek().Spelling == op {
		token := p.take()
		p.newlines()
		left = binary(token, left, p.logical(level+1, greater))
	}
	return left
}
func (p *Parser) membership(greater bool) *Expr {
	left := p.comparison(greater)
	for p.peek().Spelling == "in" {
		token := p.take()
		array := p.name()
		left = &Expr{Kind: "membership", Position: token.Position, Args: []*Expr{left}, Right: array}
	}
	return left
}
func (p *Parser) comparison(greater bool) *Expr {
	left := p.concatenation()
	for wordIn("< <= == != >= >", p.peek().Spelling) && (greater || p.peek().Spelling != ">") {
		op := p.take()
		left = binary(op, left, p.concatenation())
	}
	return left
}
func (p *Parser) concatenation() *Expr {
	left := p.additive()
	for wordIn("number string name function_name builtin", p.peek().Kind) || wordIn("$ ( ++ --", p.peek().Spelling) {
		op := Token{Spelling: "concat", Position: p.peek().Position}
		left = binary(op, left, p.additive())
	}
	return left
}
func (p *Parser) additive() *Expr {
	left := p.multiplicative()
	for p.peek().Spelling == "+" || p.peek().Spelling == "-" {
		op := p.take()
		left = binary(op, left, p.multiplicative())
	}
	return left
}
func (p *Parser) multiplicative() *Expr {
	left := p.unary()
	for wordIn("* / %", p.peek().Spelling) {
		op := p.take()
		left = binary(op, left, p.unary())
	}
	return left
}
func (p *Parser) unary() *Expr {
	if wordIn("! - +", p.peek().Spelling) {
		op := p.take()
		return &Expr{Kind: "unary", Position: op.Position, Op: op.Spelling, Left: p.unary()}
	}
	left := p.postfix()
	if p.peek().Spelling == "^" {
		op := p.take()
		left = binary(op, left, p.unary())
	}
	return left
}
func (p *Parser) prefix() *Expr {
	op := p.take()
	return &Expr{Kind: "increment", Position: op.Position, Op: op.Spelling, Prefix: true, Left: p.location()}
}
func (p *Parser) postfix() *Expr {
	if p.peek().Spelling == "++" || p.peek().Spelling == "--" {
		return p.prefix()
	}
	left := p.atom()
	if lvalue(left) && (p.peek().Spelling == "++" || p.peek().Spelling == "--") {
		op := p.take()
		return &Expr{Kind: "increment", Position: op.Position, Op: op.Spelling, Left: left}
	}
	return left
}
func (p *Parser) location() *Expr {
	if p.peek().Kind == "name" {
		name := p.name()
		if p.accept("[") {
			name.Kind = "array"
			name.Args = p.expressionList(true)
			p.expect("]")
		}
		return name
	}
	if p.accept("$") {
		position := p.Tokens[p.Index-1].Position
		var index *Expr
		if p.peek().Spelling == "++" || p.peek().Spelling == "--" {
			index = p.prefix()
		} else {
			index = p.atom()
		}
		return &Expr{Kind: "field", Position: position, Left: index}
	}
	p.fail()
	return nil
}
func (p *Parser) atom() *Expr {
	token := p.peek()
	if token.Kind == "number" || token.Kind == "string" {
		p.take()
		value := numeric(token.Number)
		if token.Kind == "string" {
			value = stringValue(token.Text)
		}
		return &Expr{Kind: token.Kind, Position: token.Position, Value: value}
	}
	if token.Kind == "name" || token.Spelling == "$" {
		return p.location()
	}
	if p.accept("(") {
		expressions := p.expressionList(true)
		p.expect(")")
		if len(expressions) == 1 {
			return &Expr{Kind: "paren", Position: token.Position, Left: expressions[0]}
		}
		p.expect("in")
		return &Expr{Kind: "membership", Position: token.Position, Args: expressions, Right: p.name()}
	}
	if token.Kind == "function_name" || token.Kind == "builtin" {
		p.take()
		arguments := []*Expr{}
		if p.accept("(") {
			if p.peek().Spelling != ")" {
				arguments = p.expressionList(true)
			}
			p.expect(")")
		} else if token.Kind == "function_name" || token.Spelling != "length" {
			p.fail()
		}
		kind := "call"
		if token.Kind == "builtin" {
			kind = "builtin"
			count := len(arguments)
			valid := count == 1
			switch token.Spelling {
			case "length":
				valid = count <= 1
			case "substr", "split":
				valid = count == 2 || count == 3
			case "index":
				valid = count == 2
			case "sprintf":
				valid = count >= 1
			}
			if !valid || token.Spelling == "split" && arguments[1].Kind != "name" {
				panic(SyntaxIssue{token.Position})
			}
		}
		return &Expr{Kind: kind, Position: token.Position, Name: token.Spelling, Args: arguments}
	}
	if p.accept("getline") {
		out := &Expr{Kind: "getline", Position: token.Position}
		if p.peek().Kind == "name" || p.peek().Spelling == "$" {
			out.Left = p.location()
		}
		if p.accept("<") {
			out.Right = p.atom()
		}
		return out
	}
	p.fail()
	return nil
}

package main

import (
	"os"
	"strings"
)

type Option struct{ Name, Value string }
type Operand struct {
	Kind, Name, Value string
	Records           int
}

func validName(name string) bool {
	if name == "" || !letter(name[0]) && name[0] != '_' {
		return false
	}
	for i := 0; i < len(name); i++ {
		if !letter(name[i]) && !digit(name[i]) && name[i] != '_' {
			return false
		}
	}
	return true
}
func validFilename(name string) bool {
	if name == "" || name[0] == '.' {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		if !letter(c) && !digit(c) && !strings.ContainsRune("._-", rune(c)) {
			return false
		}
	}
	return true
}
func parseArguments(lines []string) ([]Option, []*Operand) {
	options := []Option{}
	operands := []*Operand{}
	for _, line := range lines {
		if strings.HasPrefix(line, "-F ") {
			options = append(options, Option{"FS", line[3:]})
			continue
		}
		if strings.HasPrefix(line, "-v ") {
			a := strings.SplitN(line[3:], "=", 2)
			options = append(options, Option{a[0], a[1]})
			continue
		}
		if k := strings.IndexByte(line, '='); k >= 0 && validName(line[:k]) {
			operands = append(operands, &Operand{Kind: "assignment", Name: line[:k], Value: line[k+1:]})
		} else {
			operands = append(operands, &Operand{Kind: "file", Name: line})
		}
	}
	return options, operands
}
func readText(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	return string(data)
}
func textLines(text string) []string {
	if text == "" {
		return []string{}
	}
	return strings.Split(strings.TrimSuffix(text, "\n"), "\n")
}
func readRecords(name string) []string { return textLines(readText("input/" + name)) }

type OutputStream struct {
	Parts  []string
	Open   bool
	Writes int
}

func (s *OutputStream) content() string { return strings.Join(s.Parts, "") }

type GetlineInput struct {
	Open, EverOpened bool
	Lines            []string
	Position, Reads  int
}
type Streams struct {
	Stdout      OutputStream
	Outputs     map[string]*OutputStream
	OutputOrder []string
	Inputs      map[string]*GetlineInput
	InputOrder  []string
}

func newStreams() *Streams {
	return &Streams{Outputs: map[string]*OutputStream{}, Inputs: map[string]*GetlineInput{}}
}
func (s *Streams) write(text, name, mode string, position Position) {
	if name == "" && mode == "" {
		s.Stdout.Parts = append(s.Stdout.Parts, text)
		s.Stdout.Writes++
		return
	}
	if !validFilename(name) || name == "stdout.txt" || name == "stats.txt" {
		runtimeError(position, "invalid output file name")
	}
	stream := s.Outputs[name]
	if stream == nil {
		stream = &OutputStream{}
		s.Outputs[name] = stream
		s.OutputOrder = append(s.OutputOrder, name)
	}
	if !stream.Open {
		stream.Open = true
		if mode == ">" {
			stream.Parts = nil
		}
	}
	stream.Parts = append(stream.Parts, text)
	stream.Writes++
}
func (s *Streams) getline(name string) (int, string) {
	source := s.Inputs[name]
	if source == nil {
		source = &GetlineInput{}
		s.Inputs[name] = source
		s.InputOrder = append(s.InputOrder, name)
	}
	if !source.Open {
		if !validFilename(name) {
			return -1, ""
		}
		info, err := os.Stat("input/" + name)
		if err != nil || !info.Mode().IsRegular() {
			return -1, ""
		}
		source.Lines = readRecords(name)
		source.Position = 0
		source.Open = true
		source.EverOpened = true
	}
	if source.Position == len(source.Lines) {
		return 0, ""
	}
	line := source.Lines[source.Position]
	source.Position++
	source.Reads++
	return 1, line
}
func (s *Streams) close(name string) int64 {
	closed := false
	if output := s.Outputs[name]; output != nil && output.Open {
		output.Open = false
		closed = true
	}
	if input := s.Inputs[name]; input != nil && input.Open {
		input.Open = false
		closed = true
	}
	if closed {
		return 0
	}
	return -1
}
func writeFile(path, text string) {
	if err := os.WriteFile(path, []byte(text), 0644); err != nil {
		panic(err)
	}
}
func (s *Streams) save() {
	if err := os.MkdirAll("output", 0755); err != nil {
		panic(err)
	}
	writeFile("output/stdout.txt", s.Stdout.content())
	for _, name := range s.OutputOrder {
		writeFile("output/"+name, s.Outputs[name].content())
	}
}

package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type Value struct {
	Kind   string
	Number int64
	Text   string
}

func numeric(n int64) Value      { return Value{Kind: "number", Number: n} }
func stringValue(s string) Value { return Value{Kind: "string", Text: s} }
func whitespace(c byte) bool     { return c == ' ' || c == '\t' || c == '\n' }
func numericPrefix(text string) (int64, int, bool) {
	i := 0
	for i < len(text) && whitespace(text[i]) {
		i++
	}
	sign := int64(1)
	if i < len(text) && (text[i] == '+' || text[i] == '-') {
		if text[i] == '-' {
			sign = -1
		}
		i++
	}
	start := i
	for i < len(text) && digit(text[i]) {
		i++
	}
	if start == i {
		return 0, i, false
	}
	return sign * decimal(text[start:i]), i, true
}
func inputValue(text string) Value {
	n, end, ok := numericPrefix(text)
	for end < len(text) && whitespace(text[end]) {
		end++
	}
	if ok && end == len(text) {
		return Value{Kind: "strnum", Number: n, Text: text}
	}
	return stringValue(text)
}
func (v Value) number() int64 {
	if v.Kind == "number" || v.Kind == "strnum" {
		return v.Number
	}
	n, _, _ := numericPrefix(v.Text)
	return n
}
func (v Value) text() string {
	if v.Kind == "number" {
		return strconv.FormatInt(v.Number, 10)
	}
	return v.Text
}
func (v Value) truth() bool {
	if v.Kind == "number" || v.Kind == "strnum" {
		return v.Number != 0
	}
	return v.Kind == "string" && v.Text != ""
}
func compare(a, b Value) int {
	if a.Kind != "string" && b.Kind != "string" {
		x, y := a.number(), b.number()
		if x < y {
			return -1
		}
		if x > y {
			return 1
		}
		return 0
	}
	return strings.Compare(a.text(), b.text())
}
func integerForm(text string) bool {
	if text == "0" {
		return true
	}
	i := 0
	if strings.HasPrefix(text, "-") {
		i++
	}
	if i == len(text) || text[i] < '1' || text[i] > '9' {
		return false
	}
	for i++; i < len(text); i++ {
		if !digit(text[i]) {
			return false
		}
	}
	return true
}
func orderedSubscripts(array map[string]Value) []string {
	keys := []string{}
	for key := range array {
		keys = append(keys, key)
	}
	sort.Slice(keys, func(i, j int) bool {
		a, b := integerForm(keys[i]), integerForm(keys[j])
		if a != b {
			return a
		}
		if a {
			return decimal(keys[i]) < decimal(keys[j])
		}
		return keys[i] < keys[j]
	})
	return keys
}
func splitPieces(text, separator string) []string {
	if text == "" {
		return []string{}
	}
	if separator == " " {
		out := []string{}
		for i := 0; i < len(text); {
			for i < len(text) && whitespace(text[i]) {
				i++
			}
			start := i
			for i < len(text) && !whitespace(text[i]) {
				i++
			}
			if i > start {
				out = append(out, text[start:i])
			}
		}
		return out
	}
	if separator == "" {
		out := []string{}
		for i := 0; i < len(text); i++ {
			out = append(out, text[i:i+1])
		}
		return out
	}
	return strings.Split(text, separator)
}

type Record struct {
	Zero   Value
	Fields []Value
	Global func(string) Value
}

func (r *Record) set(text string) {
	r.Zero = inputValue(text)
	r.Fields = nil
	for _, piece := range splitPieces(text, r.Global("FS").text()) {
		r.Fields = append(r.Fields, inputValue(piece))
	}
}
func (r *Record) read(index int) Value {
	if index == 0 {
		return r.Zero
	}
	if index > len(r.Fields) {
		return Value{}
	}
	return r.Fields[index-1]
}
func (r *Record) rebuild() {
	parts := []string{}
	for _, v := range r.Fields {
		parts = append(parts, v.text())
	}
	r.Zero = inputValue(strings.Join(parts, r.Global("OFS").text()))
}
func (r *Record) resize(n int) {
	if n < len(r.Fields) {
		r.Fields = r.Fields[:n]
	}
	for len(r.Fields) < n {
		r.Fields = append(r.Fields, stringValue(""))
	}
	r.rebuild()
}
func (r *Record) write(index int, value Value) {
	if index == 0 {
		r.set(value.text())
		return
	}
	for len(r.Fields) < index {
		r.Fields = append(r.Fields, stringValue(""))
	}
	r.Fields[index-1] = value
	r.rebuild()
}
func escapedString(text string) string {
	var out strings.Builder
	out.WriteByte('"')
	for i := 0; i < len(text); i++ {
		c := text[i]
		switch c {
		case '\\':
			out.WriteString("\\\\")
		case '"':
			out.WriteString("\\\"")
		case '\n':
			out.WriteString("\\n")
		case '\t':
			out.WriteString("\\t")
		default:
			if c >= 32 && c <= 126 {
				out.WriteByte(c)
			} else {
				out.WriteString(fmt.Sprintf("\\%03o", c))
			}
		}
	}
	out.WriteByte('"')
	return out.String()
}
func describe(v Value) string {
	switch v.Kind {
	case "number":
		return v.text()
	case "string":
		return escapedString(v.Text)
	case "strnum":
		return escapedString(v.Text) + " (strnum)"
	}
	return "(uninitialized)"
}
